<script setup>
import { ref } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { api,send,session } from '../api'
const register=ref(false),email=ref(''),password=ref(''),name=ref(''),error=ref(''),busy=ref(false),router=useRouter(),route=useRoute()
function demo(role){register.value=false;email.value=role+'@harborcart.demo';password.value=role==='admin'?'AdminDemo123!':'BuyerDemo123!'}
async function submit(){error.value='';busy.value=true;try{const result=await api(register.value?'/auth/register':'/auth/login',send('POST',{email:email.value,password:password.value,...(register.value?{name:name.value}:{})}));session.token=result.token;session.user=result.user;const next=route.query.next;router.push(result.user.role==='ADMIN'?'/admin':(['/','/cart','/orders'].includes(next)?next:'/'))}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="auth-layout"><div class="auth-intro"><p class="subtle">YOUR NEXT EVERYDAY FAVORITE</p><h1>好物在此，<br>下一站是你。</h1><p>登录保存购物车，查看订单，<br>开始你的跨境购物旅程。</p><img src="/images/bag.svg" alt="帆布随身包"></div><form class="auth-form" @submit.prevent="submit"><h2>{{register?'创建你的账户':'欢迎回来'}}</h2><p class="muted">{{register?'几步开启你的好物旅程。':'登录 HarborCart，继续探索。'}}</p><label v-if="register">姓名<input v-model="name" required maxlength="60" autocomplete="name"></label><label>邮箱<input v-model="email" type="email" required maxlength="160" autocomplete="username"></label><label>密码<input v-model="password" type="password" required :minlength="register?8:1" maxlength="72" :autocomplete="register?'new-password':'current-password'"></label><p v-if="error" class="notice error" role="alert">{{error}}</p><button class="button full" :disabled="busy">{{busy?'处理中…':register?'创建账户':'登录'}}</button><button class="text-button switch-mode" type="button" @click="register=!register;error=''">{{register?'已有账户？返回登录':'还没有账户？立即注册'}}</button><div class="demo-login"><p>演示账户 · 点击填入后登录</p><button type="button" class="button secondary" @click="demo('buyer')">买家账户</button><button type="button" class="button secondary" @click="demo('admin')">运营账户</button></div></form></section></template>
